// Real LangGraph.js interrupt (your Node project)
import { interrupt } from "@langchain/langgraph";
function approvalNode(state) {
  if (state.decision.amount > 100) {
    // Pauses here with full state; resumes with the human's answer value:
    const review = interrupt({
      action: "approve refund",
      amount: state.decision.amount,
      draft: state.draft,
    });
    return { approval: review }; // { decision: 'approve' | 'edit' | 'skip', ... }
  }
  return { approval: { decision: "auto-approved" } };
}
// Resume: graph.invoke(null, { configurable: { thread_id } }) continues past the gate.

// Gate router: three human paths + auto lane (plain JS, playground-runnable)
function routeApproval(state) {
  const a = state.approval;
  if (!a || a.decision === "auto-approved") return "execute";
  if (a.decision === "approve") return "execute";
  if (a.decision === "edit") return "revalidate"; // edited state re-enters validation
  return "log-skip"; // skip (+ anything unknown): safe terminal, logged
}
// Unknown decisions fall to log-skip: fail-closed, never fail-open.

