function routeApproval(state) {
  const a = state.approval;
  if (!a || a.decision === 'auto-approved') return 'execute';
  if (a.decision === 'approve') return 'execute';
  if (a.decision === 'edit') return 'revalidate';
  return 'log-skip';
}
const cases = [
  [{}, 'execute'],
  [{ approval: { decision: 'auto-approved' } }, 'execute'],
  [{ approval: { decision: 'approve' } }, 'execute'],
  [{ approval: { decision: 'edit', draft: 'softer' } }, 'revalidate'],
  [{ approval: { decision: 'skip', reason: 'called in' } }, 'log-skip'],
  [{ approval: { decision: 'maybe??' } }, 'log-skip'],
];
let pass = 0;
for (const [s, expected] of cases) {
  const got = routeApproval(s);
  if (got === expected) pass++;
  else console.log('MISS ' + JSON.stringify(s) + ' -> ' + got);
}
console.log(pass + '/' + cases.length + ' verdicts routed');

